create type public.report_status as enum ('open','reviewing','resolved','dismissed');
alter table public.profiles add column suspended boolean not null default false;
create table public.handover_confirmations (id uuid primary key default gen_random_uuid(), claim_id uuid not null references public.claims(id) on delete cascade, confirmed_by uuid not null references public.profiles(id) on delete cascade, confirmed_at timestamptz not null default now(), unique(claim_id,confirmed_by));
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles(id) on delete cascade, reported_user_id uuid references public.profiles(id) on delete cascade, listing_id uuid references public.listings(id) on delete cascade, reason text not null check(char_length(btrim(reason)) between 3 and 120), details text, status public.report_status not null default 'open', created_at timestamptz not null default now());
create table public.moderation_actions (id uuid primary key default gen_random_uuid(), report_id uuid references public.reports(id) on delete set null, admin_id uuid not null references public.profiles(id), action text not null check(action in ('warn','suspend_user','remove_listing','dismiss')), target_user_id uuid references public.profiles(id), target_listing_id uuid references public.listings(id), notes text, created_at timestamptz not null default now());
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, endpoint text not null unique, p256dh text not null, auth text not null, created_at timestamptz not null default now());
create index reports_status_idx on public.reports(status,created_at); create index handovers_claim_idx on public.handover_confirmations(claim_id);
create or replace function public.confirm_handover(p_claim_id uuid) returns public.listing_status language plpgsql security definer set search_path='' as $$ declare listing_id uuid; claimant uuid; finder uuid; confirmations integer; result public.listing_status; begin select c.listing_id,c.claimant_id,l.poster_id into listing_id,claimant,finder from public.claims c join public.listings l on l.id=c.listing_id where c.id=p_claim_id and c.status='accepted' and l.status in ('claimed','return_pending'); if listing_id is null or auth.uid() not in (claimant,finder) then raise exception 'Only parties to an accepted claim can confirm handover'; end if; insert into public.handover_confirmations(claim_id,confirmed_by) values(p_claim_id,auth.uid()) on conflict do nothing; select count(*) into confirmations from public.handover_confirmations where claim_id=p_claim_id and confirmed_by in (claimant,finder); update public.listings set status=case when confirmations=2 then 'returned' else 'return_pending' end where id=listing_id returning status into result; return result; end; $$;
create or replace function public.decide_report(p_report_id uuid,p_status public.report_status,p_action text default null,p_notes text default null) returns void language plpgsql security definer set search_path='' as $$ declare target_user uuid; target_listing uuid; begin if not public.current_user_is_admin() then raise exception 'Admin access required'; end if; select reported_user_id,listing_id into target_user,target_listing from public.reports where id=p_report_id; if not found then raise exception 'Report not found'; end if; update public.reports set status=p_status where id=p_report_id; if p_action is not null then insert into public.moderation_actions(report_id,admin_id,action,target_user_id,target_listing_id,notes) values(p_report_id,auth.uid(),p_action,target_user,target_listing,p_notes); if p_action='remove_listing' and target_listing is not null then update public.listings set status='closed' where id=target_listing; elsif p_action='suspend_user' and target_user is not null then update public.profiles set suspended=true where id=target_user; end if; end if; end; $$;
create or replace function public.review_college(p_college_id uuid,p_approve boolean,p_publicly_discoverable boolean default false) returns void language plpgsql security definer set search_path='' as $$ begin if not public.current_user_is_admin() then raise exception 'Admin access required'; end if; update public.colleges set status=case when p_approve then 'approved' else 'rejected' end, publicly_discoverable=case when p_approve then p_publicly_discoverable else false end, reviewed_by=auth.uid(), reviewed_at=now() where id=p_college_id and status='pending'; if not found then raise exception 'Pending college not found'; end if; end; $$;
create or replace function public.set_college_discoverable(p_college_id uuid,p_enabled boolean) returns void language plpgsql security definer set search_path='' as $$ begin if not public.current_user_is_admin() then raise exception 'Admin access required'; end if; update public.colleges set publicly_discoverable=p_enabled where id=p_college_id and status='approved'; end; $$;
alter table public.handover_confirmations enable row level security; alter table public.reports enable row level security; alter table public.moderation_actions enable row level security; alter table public.push_subscriptions enable row level security;
create policy "parties view handovers" on public.handover_confirmations for select to authenticated using(exists(select 1 from public.claims c join public.listings l on l.id=c.listing_id where c.id=claim_id and (c.claimant_id=(select auth.uid()) or l.poster_id=(select auth.uid())))); create policy "parties confirm handovers" on public.handover_confirmations for insert to authenticated with check(confirmed_by=(select auth.uid())); create policy "reporters and admins view reports" on public.reports for select to authenticated using(reporter_id=(select auth.uid()) or public.current_user_is_admin()); create policy "users create reports" on public.reports for insert to authenticated with check(reporter_id=(select auth.uid())); create policy "admins view actions" on public.moderation_actions for select to authenticated using(public.current_user_is_admin()); create policy "own push subscriptions" on public.push_subscriptions for all to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()));
revoke all on public.handover_confirmations,public.reports,public.moderation_actions,public.push_subscriptions from anon,authenticated; grant select,insert on public.handover_confirmations to authenticated; grant select,insert on public.reports to authenticated; grant select on public.moderation_actions to authenticated; grant select,insert,update,delete on public.push_subscriptions to authenticated; revoke execute on function public.confirm_handover(uuid),public.decide_report(uuid,public.report_status,text,text),public.review_college(uuid,boolean,boolean),public.set_college_discoverable(uuid,boolean) from public,anon; grant execute on function public.confirm_handover(uuid),public.decide_report(uuid,public.report_status,text,text),public.review_college(uuid,boolean,boolean),public.set_college_discoverable(uuid,boolean) to authenticated;
